  // Glossary of Insurance Terms (Kamus Istilah)
  glossary: [
    { term: "Gross Written Premium (GWP)", definition: "Total pendapatan premi kotor yang ditulis oleh perusahaan asuransi sebelum dikurangi premi yang didelegasikan ke reasuradur." },
    { term: "Reinsurance Ceded (RWP)", definition: "Bagian premi yang dialihkan/dibayarkan kepada perusahaan reasuransi (reasuradur) untuk mentransfer sebagian risiko kerugian." },
    { term: "Net Written Premium (NWP)", definition: "Premi yang ditahan sendiri oleh perusahaan asuransi setelah dikurangi premi reasuransi (NWP = GWP - RWP)." },
    { term: "Gross Paid Claims (GRS_ST)", definition: "Total pembayaran klaim kotor yang telah diselesaikan oleh perusahaan kepada pemegang polis." },
    { term: "Gross Outstanding Claims (OS)", definition: "Cadangan klaim kotor, yaitu estimasi kewajiban pembayaran klaim yang sudah terjadi namun pembayarannya masih dalam proses." },
    { term: "Gross Incurred Claims (GIC)", definition: "Total klaim yang terjadi pada suatu periode kotor, mencakup klaim yang sudah dibayar ditambah dengan cadangan klaim (GIC = Gross Paid + Gross OS)." },
    { term: "Reinsurance Recovery (RI)", definition: "Klaim pemulihan dari perusahaan reasuransi, yaitu bagian klaim yang ditanggung oleh reasuradur sesuai porsi treaty transfer risiko." },
    { term: "Net Incurred Claims (NIC)", definition: "Klaim beban bersih perusahaan asuransi setelah dikurangi klaim pemulihan reasuransi (NIC = Gross Incurred - RI Recovery)." },
    { term: "Loss Ratio (Rasio Klaim)", definition: "Rasio perbandingan antara total klaim incurred dengan premi written. Menunjukkan tingkat profitabilitas underwriting. Formula: (Incurred Claims / Written Premium) * 100%." },
    { term: "Exposure (Sum Insured)", definition: "Total uang pertanggungan atau nilai maksimum liabilitas keuangan yang dijamin oleh perusahaan asuransi atas polis-polis yang diterbitkan." },
    { term: "Claim Severity", definition: "Rasio rata-rata besaran nominal kerugian per satu kali kejadian klaim (Total Nilai Klaim / Jumlah Klaim)." }
  ],
